    top_module dut (
        .clk(clk),
        .data_in(data_in),
        .pop(pop),
        .push(push),
        .reset(reset),
        .data_out(data_out),
        .empty(empty),
        .full(full)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

    begin
        reset = 1;
        push = 0;
        pop = 0;
        data_in = 8'h0;
        @(posedge clk);
        #1 reset = 0;
        @(posedge clk);
    end
        endtask
    task testcase001;

    begin
        $display("\nTestcase 001: Reset State");
        reset_dut();

        #1;


        check_outputs(8'hxx, 1'b1, 1'b0);
    end
        endtask

    task testcase002;

    begin
        $display("\nTestcase 002: Single Push and Pop");
        reset_dut();


        data_in = 8'hA5;
        push = 1;
        @(posedge clk);
        push = 0;
        @(posedge clk);


        pop = 1;
        @(posedge clk);
        pop = 0;


        #1;



        check_outputs(8'hA5, 1'b1, 1'b0);
    end
        endtask

    task testcase003;

    begin
        $display("\nTestcase 003: Sequential Push and Pop (Ordering)");
        reset_dut();


        push = 1; data_in = 8'h11; @(posedge clk);
        push = 1; data_in = 8'h22; @(posedge clk);
        push = 1; data_in = 8'h33; @(posedge clk);
        push = 0;
        @(posedge clk);


        pop = 1; @(posedge clk);

        pop = 1; @(posedge clk);

        pop = 1; @(posedge clk);
        pop = 0;


        #1;



        check_outputs(8'h33, 1'b1, 1'b0);
    end
        endtask

    task testcase004;

    integer i;
    begin
        $display("\nTestcase 004: Fill to Full");
        reset_dut();


        push = 1;
        for(i=0; i<16; i=i+1) begin
            data_in = i[7:0];
            @(posedge clk);
            if (full) i = 20;
        end
        push = 0;
        @(posedge clk);


        #1;



        check_outputs(8'hxx, 1'b0, 1'b1);
    end
        endtask

    task testcase005;

    integer i;
    begin
        $display("\nTestcase 005: Emptying FIFO from Full");
        reset_dut();


        push = 1;
        for(i=0; i<8; i=i+1) begin
            data_in = i[7:0] + 8'h10;
            @(posedge clk);
        end
        push = 0;
        @(posedge clk);


        pop = 1;
        while (!empty) begin
            @(posedge clk);
        end
        pop = 0;


        #1;



        check_outputs(8'hxx, 1'b1, 1'b0);
    end
        endtask

    // Test stimulus
