module top_module(
    input A, B, C, D,
    input [1:0] sel,
    input clk,            // Added clk input
    output reg Y
);reg [1:0] stage1_sel;
reg [1:0] stage2_sel;

always @(*) begin
    stage1_sel = sel;
    stage2_sel = stage1_sel;
end

