    case (stage2_sel)
        2'b00: Y <= A;
        2'b01: Y <= B;
        2'b10: Y <= C;
        2'b11: Y <= D;
        default: Y <= 1'b0; // Optional: Ensure Y is defined for all cases
    endcase
end

endmodule

