description:
Design a sequence detector that identifies a specific 3-bit pattern in a serial input data stream. The module transitions through four states in response to the input clock and data signals: starting from an initial state (000), it recognizes a sequence of three consecutive '1's (111). Upon detecting this pattern, it asserts the output signal `match` and then resets to the initial state. If the sequence is interrupted by a '0', the module returns to the initial state, indicating it has not found the desired pattern.
module top_module(
  input clk,
  input data,
  output reg match
);

code:
module top_module(
  input clk,
  input data,
  output reg match
);reg [2:0] state;

always @(posedge clk) begin
  case(state)
    3'b000: if(data) state <= 3'b001;
            else state <= 3'b000;
    3'b001: if(data) state <= 3'b010;
            else state <= 3'b000;
    3'b010: if(data) begin
              state <= 3'b011;
              match <= 1;
            end
            else state <= 3'b000;
    3'b011: begin
              state <= 3'b000;
              match <= 0;
            end
  endcase
end

endmodule

