module top_module(
  aclr,
  data,
  rdclk,
  rdreq,
  wrclk,
  wrreq,
  q,
  rdempty,
  wrusedw
);parameter WIDTH = 16;
  parameter DEPTH = 8;

  input aclr;
  input [WIDTH-1:0] data;
  input rdclk;
  input rdreq;
  input wrclk;
  input wrreq;
  output reg [WIDTH-1:0] q; // Changed output to reg
  output rdempty;
  output [clog2(DEPTH)-1:0] wrusedw; // Changed to clog2 for constant size

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [clog2(DEPTH)-1:0] rdptr;
  reg [clog2(DEPTH)-1:0] wrptr;
  reg [clog2(DEPTH)+1:0] count;

  always @ (posedge wrclk) begin
    if (wrreq) begin
      mem[wrptr] <= data;
      wrptr <= (wrptr == DEPTH-1) ? 0 : wrptr + 1;
      count <= count + 1;
    end
  end

  always @ (posedge rdclk) begin
    if (rdreq && !rdempty) begin
      q <= mem[rdptr];
      rdptr <= (rdptr == DEPTH-1) ? 0 : rdptr + 1;
      count <= count - 1;
    end
  end

  assign rdempty = (count == 0);
  assign wrusedw = count;

  always @ (posedge aclr) begin
    if (aclr) begin
      rdptr <= 0;
      wrptr <= 0;
      count <= 0;
      q <= 0; // Initialize q on aclr
    end
  end

  // Function to compute the log base 2
  function integer clog2;
    input integer value;
    begin
      value = value - 1;
      for (clog2 = 0; value > 0; clog2 = clog2 + 1)
        value = value >> 1;
    end
  endfunction

endmodule

