module top_module(
      input  [7:0] io_dataIn,
      output reg [7:0] io_dataOut, // Change from wire to reg
      input   io_read,
      input   io_write,
      output  io_full,
      output  io_empty,
      input   clk,
      input   reset
    );localparam DEPTH = 32;

    reg [7:0] mem [0:DEPTH-1];
    reg [4:0] head, tail;
    reg [4:0] next_head, next_tail;
    reg full, empty;
    wire write_en, read_en;

    assign write_en = io_write && !full;
    assign read_en = io_read && !empty;

    always @(posedge clk) begin
        if (reset) begin
            head <= 0;
            tail <= 0;
            full <= 0;
            empty <= 1;
        end else begin
            head <= next_head;
            tail <= next_tail;
            full <= (head == next_tail) && !empty;
            empty <= (tail == next_head) && !full;
        end
    end

    always @(posedge clk) begin
        if (write_en) begin
            mem[head] <= io_dataIn;
            next_head <= (head + 1) % DEPTH;
        end else begin
            next_head <= head;
        end

        if (read_en) begin
            io_dataOut <= mem[tail]; // Keep this line here
            next_tail <= (tail + 1) % DEPTH;
        end else begin
            next_tail <= tail;
        end
    end

    assign io_full = full;
    assign io_empty = empty;

endmodule

