module shift_register(
	input clk,
	input load,
	input [3:0] d,
	output reg q
);

	reg [3:0] shift_reg;

	always @(posedge clk) begin
		if (load)
			shift_reg <= d;
		else
			shift_reg <= {1'b0, shift_reg[3:1]};
		q <= shift_reg[0];
	end

endmodule

