module top_module(
  input clk,
  input data_in,
  input waveform_type,
  output reg waveform_out,
  output reg waveform_done
);reg [1:0] state;

always @(posedge clk) begin
  case (state)
    2'b00: begin // FM0
      waveform_out <= data_in;
      waveform_done <= 0;
      if (waveform_type == 2'b01) begin
        state <= 2'b01;
      end
    end
    2'b01: begin // M2
      waveform_out <= waveform_out ^ data_in;
      waveform_done <= 0;
      if (waveform_type == 2'b10) begin
        state <= 2'b10;
      end
    end
    2'b10: begin // M4
      waveform_out <= waveform_out ^ 1'b1;
      waveform_done <= 0;
      if (waveform_type == 2'b00) begin
        state <= 2'b00;
        waveform_done <= 1;
      end
    end
    default: begin
      state <= 2'b00;
      waveform_out <= 0;
      waveform_done <= 0;
    end
  endcase
end

endmodule

