module async_counter_with_load(
    input clk,
    input async_reset,
    input enable,
    input load,
    input [3:0] parallel_in,
    output reg [3:0] count_out
);

    always @(posedge clk or posedge async_reset) begin
        if (async_reset)
            count_out <= 4'b0000;
        else if (load)
            count_out <= parallel_in;
        else if (enable)
            count_out <= count_out + 1;
    end

endmodule

