module shift_register (D, CLK, LOAD, Q);
input [7:0] D;
input CLK;
input LOAD;
output reg [7:0] Q;

always @(posedge CLK) begin
    if (LOAD) begin
        Q <= D;
    end
    else begin
        Q <= {1'b0, Q[7:1]};
    end
end

endmodule

