module top_module(
    input signed [7:0] A,
    input signed [7:0] B,
    input ready,
    output reg valid,
    output reg signed [15:0] product
);reg signed [7:0] a_reg;
reg signed [7:0] b_reg;
reg signed [7:0] b_neg;
reg signed [15:0] p_reg;
reg [3:0] state;

always @(posedge ready) begin
    if (state == 0) begin
        a_reg <= A;
        b_reg <= B;
        b_neg <= ~B + 1;
        p_reg <= {8'b0, a_reg};
        state <= 1;
    end else if (state == 1) begin
        if (b_reg[0] == 1 && b_reg != 1'b1) begin
            p_reg <= p_reg - b_neg;
            b_reg <= b_reg + 1;
            state <= 2;
        end else begin
            state <= 3;
        end
    end else if (state == 2) begin
        if (p_reg[0] == 1) begin
            p_reg <= p_reg + b_reg;
        end
        if (b_reg[0] == 1 && b_reg != 1'b1) begin
            p_reg <= p_reg - b_neg;
            b_reg <= b_reg + 1;
        end else begin
            state <= 3;
        end
    end else if (state == 3) begin
        product <= p_reg[15:0];
        valid <= 1;
        state <= 0;
    end
end

endmodule

