module top_module(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data1,
    input [3:0] data2,
    output reg [3:0] q
);reg [3:0] shift_reg1;
reg [3:0] shift_reg2;

// Shift registers with asynchronous reset, synchronous load, and enable
always @(posedge clk or posedge areset) begin
    if (areset) begin
        shift_reg1 <= 4'b0;
        shift_reg2 <= 4'b0;
    end else begin
        if (load & ena) begin
            shift_reg1 <= data1;
            shift_reg2 <= data2;
        end else if (load) begin
            shift_reg1 <= data1;
        end else if (ena) begin
            shift_reg2 <= data2;
        end else begin
            shift_reg1 <= {shift_reg1[2:0], shift_reg1[3]};
            shift_reg2 <= {shift_reg2[2:0], shift_reg2[3]};
        end
    end
end

// Functional module that computes the bitwise AND of the two shift registers
assign q = shift_reg1 & shift_reg2;

endmodule

