module top_module(
    input A0,
    input A1,
    input A2,
    input A3,
    input S0,
    input S1,
    output X,
    input VPB,
    input VPWR,
    input VGND,
    input VNB
);reg [3:0] inputs;
reg [1:0] select;

always @ (posedge S0, negedge S0, posedge S1, negedge S1) begin
    select[0] <= S0;
    select[1] <= S1;
end

always @ (select or A0 or A1 or A2 or A3) begin
    case (select)
        2'b00: inputs = {A0, 1'b0, 1'b0, 1'b0};
        2'b01: inputs = {1'b0, A1, 1'b0, 1'b0};
        2'b10: inputs = {1'b0, 1'b0, A2, 1'b0};
        2'b11: inputs = {1'b0, 1'b0, 1'b0, A3};
    endcase
end

assign X = inputs[3] | inputs[2] | inputs[1] | inputs[0];

endmodule

module top_module(
	input rst_n,               
	input clk,                 
	input[11:0] top,           
	input[11:0] left,          
	input[11:0] width,         
	input[11:0] height,        
	input[11:0] x,             
	input[11:0] y,             
	input[7:0] i_alpha,        
	output reg[7:0] o_alpha,   
	output rdreq               
);reg rdreq_d0;

assign rdreq = (y > top) && (y <= top + height) && (x > left) && (x <= left + width);
always@(posedge clk)
begin
	rdreq_d0 <= rdreq;
end

always@(posedge clk or negedge rst_n)
begin
	if(~rst_n)
		o_alpha <= 8'd0;
	else if(rdreq_d0)
		o_alpha <= i_alpha;
	else
		o_alpha <= 8'd0;
end
endmodule

