module top_module(

   clk_50m, locked,

   clk_in, resetn
   );input clk_in;
   output clk_50m;
   input  resetn;
   output locked;






   reg                  clk_50m;
   reg                  locked;



   always @(posedge clk_in or negedge resetn) begin
      if(resetn == 1'b0) begin


         clk_50m <= 1'h0;

      end
      else begin
         clk_50m <= !clk_50m;
      end
   end

   always @(posedge clk_50m or negedge resetn) begin
      if(resetn == 1'b0) begin


         locked = 1'h0;

      end
      else begin
         locked <= 1'b1;

      end
   end



endmodule

module top_module(	input wire clk,
							input wire [4:0] button, 
							input wire [7:0] SW,
							output reg [4:0]button_out, 
							output reg [4:0]button_pluse, 
							output reg [7:0] SW_OK
							);reg [31:0] counter; 
	reg [4:0] btn_temp; 
	reg [7:0] sw_temp; 
	reg pluse;

	always @(posedge clk) begin
		btn_temp <= button;
		sw_temp <= SW;
		if(btn_temp !=button || sw_temp !=SW) begin
			counter <= 32'h00000000; 
			pluse <= 0;
			end
		else if(counter<100000)
			counter<=counter+1;
			else begin 
			button_out<=button; 
			pluse <= 1; 
			if(!pluse)
				button_pluse <= button; 
			else button_pluse <= 0; 
			SW_OK <= SW;
			end
	end

endmodule

