module top_module(
    input clk,
    input clk_100k,
    input reset,
    output [7:0]sawtooth_wave
    );localparam res = 0, step = 1;
    reg state, next_state;
    reg [7:0] count, next_count;

    always@(negedge clk_100k, posedge reset)begin
        if(reset)begin
            state <= res;
            count <= 0;
        end
        else begin
            state <= next_state;
            count <= next_count;
        end
    end

    always@(state, count)begin
        case(state)
            res: begin
                next_count = 0;
                next_state = step;
            end
            step: begin
                next_count = count+2;
                if((count+2)>=128) next_state = res;
                else next_state = step;
            end
            default:
                next_state = res;
        endcase
    end 

    assign sawtooth_wave = count;


































endmodule

module multiplier_8bit (
    input wire [7:0] a,
    input wire [7:0] b,
    output wire [15:0] y
);

    wire [15:0] part1, part2, part3, part4;

    mult4 mult4_inst1 (
        .a(a[7:4]),
        .b(b[7:4]),
        .y(part1)
    );

    mult4 mult4_inst2 (
        .a(a[7:4]),
        .b(b[3:0]),
        .y(part2)
    );

    mult4 mult4_inst3 (
        .a(a[3:0]),
        .b(b[7:4]),
        .y(part3)
    );

    mult4 mult4_inst4 (
        .a(a[3:0]),
        .b(b[3:0]),
        .y(part4)
    );

    assign y = part1 + (part2 << 4) + (part3 << 4) + (part4 << 8);

endmodule

module mult4 (
    input wire [3:0] a,
    input wire [3:0] b,
    output wire [7:0] y
);
    assign y = a * b;
