module top_module(
    input clk,
    input slowena,
    input reset,
    input a,
    input b,
    input sel,
    output [7:0] out
);reg [3:0] count;
wire enable;

// Decade Counter
always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
        count <= 0;
    end else if (slowena == 1) begin
        if (count == 9) begin
            count <= 0;
        end else begin
            count <= count + 1;
        end
    end
end

// Multiplexer
assign enable = (sel == 0) ? a : b;

// Functional Module
assign out = count + enable;

endmodule

module top_module(
    input clk,
    input reset_n,
    input load,
    input ena,
    input [19:0] data,
    output reg [19:0] q);always @(posedge clk or negedge reset_n) begin
		if (!reset_n)
			q <= 0;
		else if (load)
			q <= data;
		else if (ena)
			q <= {1'b0, q[19:1]};
	end
endmodule

module top_module(clk, in, out);input clk;
input [3:0] in;
output [2:0] out;
reg [2:0] out;

always @(posedge clk) begin
    case (in)
        4'b0000, 4'b0001, 4'b0010, 4'b0011:
            out <= {in[2:0], 1'b0};
        4'b1000, 4'b1001, 4'b1010, 4'b1011:
            out <= {1'b0, in[3:1]};
        default:
            out <= 3'b0;
    endcase
end

endmodule

