reg signed [width-1:0] ain, bin;
always @(a, b) begin
  equal = 0;
  greater = 0; 
  lower = 0;
  ain = a;
  bin = b;
  tmp = ain - bin;
  if(!tmp) begin
    equal = 1;
  end else if(tmp[width]) begin 
     lower = 1;
  end else begin
     greater = 1;
  end
end
endmodule

