module top_module(
  input clk,
  input reset,
  input [3:0] A,
  input [3:0] B,
  output reg [7:0] P
);reg [4:0] A_reg, B_reg, B_neg;
reg [2:0] counter;
reg [7:0] P_reg;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    A_reg <= 0;
    B_reg <= 0;
    B_neg <= 0;
    counter <= 0;
    P_reg <= 0;
  end else begin
    A_reg <= A;
    B_reg <= B;
    B_neg <= ~B + 1;
    counter <= 3;
    P_reg <= 0;
  end
end

always @(posedge clk) begin
  if (counter > 0) begin
    if (B_reg[0] == 1 && B_reg[1] == 0) begin
      P_reg <= P_reg + (A_reg << (counter-1));
      B_reg <= B_reg + 1;
    end else if (B_reg[0] == 0 && B_reg[1] == 1) begin
      P_reg <= P_reg + (B_neg << (counter-1));
      B_reg <= B_reg - 1;
    end
    B_reg <= {B_reg[2:0], B_reg[3]};
    counter <= counter - 1;
  end else begin
    P <= P_reg;
  end
end

endmodule

