module fsm (
	input clk,
	input reset_n,
	input i,
	input j,
	output reg p);

	parameter A=0, B=1, S1=2, S2=3;
	reg [1:0] state, next;

	always @(posedge clk) begin
		if (!reset_n) state <= A;
		else state <= next;
	end

	always_comb begin
		case (state)
			A: next = i ? B : A;
			B: next = j ? S1 : S2;
			S1: next = j ? S2 : A;
			S2: next = i ? B : A;
			default: next = 'x;
		endcase
	end

	assign p = (state == S1);

endmodule

