module top_module(dout, empty, full, wr_data_count, rd_en, wr_en, rd_clk, wr_clk, din, rst);parameter WIDTH = 32;
    parameter DEPTH = 256;
    parameter ADDR_BITS = $clog2(DEPTH);
    parameter DATA_BITS = WIDTH;
    parameter ADDR_MASK = DEPTH-1;

    input rd_en, wr_en, rd_clk, wr_clk, rst;
    input [DATA_BITS-1:0] din;
    output [DATA_BITS-1:0] dout;
    output empty, full;
    output reg [1:0] wr_data_count;

    reg [ADDR_BITS-1:0] wr_ptr;
    reg [ADDR_BITS-1:0] rd_ptr;
    reg [DATA_BITS-1:0] mem [0:DEPTH-1];
    reg [1:0] data_count;
    reg [1:0] next_data_count; // Change from wire to reg
    reg [1:0] next_wr_data_count; // Change from wire to reg
    wire [1:0] next_rd_data_count;

    assign dout = mem[rd_ptr];
    assign empty = (data_count == 0);
    assign full = (data_count == DEPTH);

    always @(posedge wr_clk or posedge rst) begin
        if (rst) begin
            wr_ptr <= 0;
            wr_data_count <= 0;
        end
        else if (wr_en) begin
            mem[wr_ptr] <= din;
            wr_ptr <= wr_ptr + 1;
            wr_data_count <= next_wr_data_count;
        end
    end

    always @(posedge rd_clk or posedge rst) begin
        if (rst) begin
            rd_ptr <= 0;
            data_count <= 0;
        end
        else if (rd_en) begin
            rd_ptr <= rd_ptr + 1;
            data_count <= next_data_count;
        end
    end

    always @(*) begin
        next_data_count = data_count - rd_en + wr_en;
        next_wr_data_count = wr_data_count + wr_en - rd_en;
    end

    always @(posedge wr_clk or posedge rst) begin
        if (rst) begin
            data_count <= 0;
        end
        else if (wr_en) begin
            data_count <= next_data_count; // Fix here to use next_data_count
        end
    end

endmodule

