module top_module(
    output Y,
    input  A,
    input  B,
    input  C,
    input  D
);wire n1, n2, n3, n4, n5;

    // Implementing a NOR3 gate behavior
    function nor3(input A, input B, input C);
        begin
            nor3 = ~(A | B | C);
        end
    endfunction

